#define NY_MODEL 15
#define NU_MODEL 15
static float sil_y_hist[NY_MODEL] = {0};
static float sil_u_hist[NU_MODEL] = {0};

static float simulate_narx(float u_atual) {
    for (int i = NU_MODEL - 1; i > 0; i--) sil_u_hist[i] = sil_u_hist[i-1];
    sil_u_hist[0] = u_atual;

    float y_k = 1.4453516339161712f * (sil_y_hist[0])
              + -0.15763384661289287f * (sil_y_hist[1])
              + 0.03186000306800809f * (sil_y_hist[14])
              + -0.12955619806248944f * (sil_y_hist[3])
              + 5.441039764206217e-06f * (sil_u_hist[2] * sil_u_hist[5])
              + 4.8057671941595836e-06f * (sil_y_hist[0] * sil_y_hist[0])
              + -0.08485785214159239f * (sil_y_hist[8])
              + 1.336143189451035e-05f * (sil_u_hist[5] * sil_u_hist[9])
              + -0.0053649645115774625f * 1.0f
              + -0.10615592523256359f * (sil_y_hist[2]);

    for (int i = NY_MODEL - 1; i > 0; i--) sil_y_hist[i] = sil_y_hist[i-1];
    sil_y_hist[0] = y_k;
    return y_k;
}

static inline float relu(float x) { return (x > 0.0f) ? x : 0.0f; }

static float ann_predict(float *input) {
    float h1[128] = {0};
    float h2[128] = {0};
    float out = 0.0f;

    float norm_input[330];
    for (int i = 0; i < 330; i++) {
        norm_input[i] = (input[i] - scaler_mean[i]) / scaler_scale[i];
    }

    for (int i = 0; i < 128; i++) {
        float sum = b0[i];
        for (int j = 0; j < 330; j++) {
            sum += W0[i * 330 + j] * norm_input[j];
        }
        h1[i] = relu(sum);
    }

    for (int i = 0; i < 128; i++) {
        float sum = b1[i];
        for (int j = 0; j < 128; j++) {
            sum += W1[i * 128 + j] * h1[j];
        }
        h2[i] = relu(sum);
    }

    out = b2[0];
    for (int i = 0; i < 128; i++) {
        out += W2[i] * h2[i];
    }

    if (out > 80.0f) out = 80.0f;
    if (out < -10.0f) out = -10.0f;
    return out;
}

